'use strict';

const { HttpsError } = require('firebase-functions/v2/https');
const { getFirestore, FieldValue } = require('firebase-admin/firestore');
const { pathToFileURL } = require('node:url');
const path = require('node:path');

// Generated by functions/scripts/sync-domain.cjs. Never edit the generated ledger.
const ledgerPromise = import(pathToFileURL(path.join(__dirname, '../shared/LedgerCalculations.js')).href);
const REQUEST_ID = /^[A-Za-z0-9_-]{1,110}$/;
const OPERATIONS = {
  opening: { name: 'initializeAccount', eventPrefix: 'opening' },
  income: { name: 'recordIncome', eventPrefix: 'income' },
  expense: { name: 'recordExpense', eventPrefix: 'expense' },
  allocate: { name: 'allocateFunds', eventPrefix: 'allocate' },
  release: { name: 'releaseFunds', eventPrefix: 'release' },
  transfer: { name: 'transferFunds', eventPrefix: 'transfer' },
};

function authenticate(request) {
  const uid = request.auth?.uid;
  if (typeof uid !== 'string' || !uid) {
    throw new HttpsError('unauthenticated', 'Sign in before changing financial data.');
  }
  return uid;
}

function parseCommand(request, kind) {
  const data = request.data;
  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    throw new HttpsError('invalid-argument', 'Command data must be an object.');
  }
  const { requestId, amountCents, effectiveDate } = data;
  if (typeof requestId !== 'string' || !REQUEST_ID.test(requestId)) {
    throw new HttpsError('invalid-argument', 'requestId must use 1–110 letters, digits, _ or -.');
  }
  const expected = ['requestId', 'amountCents', 'effectiveDate'];
  if (['expense', 'release', 'transfer'].includes(kind)) expected.push('sourceKey');
  if (['allocate', 'transfer'].includes(kind)) expected.push('destinationKey');
  if (Object.keys(data).some((key) => !expected.includes(key))) {
    throw new HttpsError('invalid-argument', 'Unrecognized command fields.');
  }
  return {
    requestId, amountCents, effectiveDate,
    ...(expected.includes('sourceKey') ? { sourceKey: data.sourceKey } : {}),
    ...(expected.includes('destinationKey') ? { destinationKey: data.destinationKey } : {}),
  };
}

function asBadInput(error) {
  if (error instanceof HttpsError) throw error;
  if (error instanceof RangeError || error instanceof TypeError) {
    throw new HttpsError('invalid-argument', error.message);
  }
  throw error;
}

function existingAccounts(previous, ledger) {
  if (!previous || !Number.isSafeInteger(previous.trackedTotalCents) ||
      !Number.isSafeInteger(previous.unallocatedCents)) {
    throw new HttpsError('failed-precondition', 'Invalid or missing financial summary.');
  }
  // Legacy opening summaries did not include accounts; support those on first update.
  const accounts = previous.accounts ?? { unallocated: previous.unallocatedCents };
  if (!accounts || typeof accounts !== 'object' || Array.isArray(accounts)) {
    throw new HttpsError('failed-precondition', 'Malformed stored account balances.');
  }
  let computed;
  try {
    for (const cents of Object.values(accounts)) {
      if (!Number.isSafeInteger(cents)) throw new TypeError('Invalid stored balance');
    }
    computed = ledger.ledgerSummary({ accounts, receipts: {} });
  } catch {
    throw new HttpsError('failed-precondition', 'Malformed stored account balances.');
  }
  for (const [field, amount] of Object.entries(computed)) {
    if (previous[field] !== undefined && previous[field] !== amount) {
      throw new HttpsError('failed-precondition', 'Stored summary is inconsistent.');
    }
  }
  if (previous.trackedTotalCents !== computed.trackedTotalCents ||
      previous.unallocatedCents !== computed.unallocatedCents) {
    throw new HttpsError('failed-precondition', 'Stored summary is inconsistent.');
  }
  return accounts;
}

function createEvent(ledger, kind, meta, command, accounts) {
  const { amountCents, sourceKey, destinationKey } = command;
  switch (kind) {
    case 'opening': return ledger.openingBalance(meta, amountCents);
    case 'income': return ledger.recordIncome(meta, amountCents);
    case 'expense': return ledger.recordExpense(meta, amountCents, sourceKey, accounts[sourceKey] ?? 0);
    case 'allocate': return ledger.allocate(meta, amountCents, destinationKey);
    case 'release': return ledger.release(meta, amountCents, sourceKey);
    case 'transfer': return ledger.transfer(meta, amountCents, sourceKey, destinationKey);
    default: throw new Error(`Unsupported operation: ${kind}`);
  }
}

async function performOperation(request, kind) {
  const uid = authenticate(request);
  const command = parseCommand(request, kind);
  const { requestId, effectiveDate, amountCents } = command;
  const ledger = await ledgerPromise;
  const eventId = `${OPERATIONS[kind].eventPrefix}_${requestId}`;
  const meta = { eventId, requestId, effectiveDate };

  // Validate amount and date before Firestore access. Balance-dependent validation
  // must happen inside the transaction using the authoritative stored accounts.
  try {
    if (kind === 'opening' || kind === 'income') {
      createEvent(ledger, kind, meta, command, { unallocated: 0 });
    } else {
      ledger.createEvent({ ...meta, eventType: kind === 'allocate' ? 'allocate' : kind,
        amountCents, postings: [
          { accountKey: 'external', deltaCents: -amountCents },
          { accountKey: 'unallocated', deltaCents: amountCents },
        ] });
    }
  } catch (error) { asBadInput(error); }

  const fingerprint = JSON.stringify({
    kind, amountCents, effectiveDate,
    ...(Object.hasOwn(command, 'sourceKey') ? { sourceKey: command.sourceKey } : {}),
    ...(Object.hasOwn(command, 'destinationKey') ? { destinationKey: command.destinationKey } : {}),
  });

  const base = getFirestore().collection('users').doc(uid);
  const operationRef = base.collection('operations').doc(requestId);
  const summaryRef = base.collection('summaries').doc('current');
  const journalRef = base.collection('journal').doc(eventId);
  const transactionRef = ['income', 'expense'].includes(kind)
    ? base.collection('transactions').doc(eventId) : null;

  return getFirestore().runTransaction(async (tx) => {
    const [receiptSnap, summarySnap] = await Promise.all([
      tx.get(operationRef), tx.get(summaryRef),
    ]);
    if (receiptSnap.exists) {
      const prior = receiptSnap.data();
      // Prior released version used eventType instead of kind in receipts.
      const legacyFingerprint = JSON.stringify({
        eventType: kind === 'opening' ? 'opening_balance' : kind,
        amountCents, effectiveDate,
      });
      if (prior.fingerprint !== fingerprint &&
          !(['opening', 'income'].includes(kind) && prior.fingerprint === legacyFingerprint)) {
        throw new HttpsError('already-exists', 'Request ID already used with different data.');
      }
      return { ...prior.result, duplicate: true };
    }
    if (kind === 'opening' && summarySnap.exists) {
      throw new HttpsError('failed-precondition', 'Account already initialized.');
    }
    if (kind !== 'opening' && !summarySnap.exists) {
      throw new HttpsError('failed-precondition', 'Initialize account before financial operations.');
    }

    let event, state;
    try {
      const accounts = kind === 'opening'
        ? { unallocated: 0 } : existingAccounts(summarySnap.data(), ledger);
      event = createEvent(ledger, kind, meta, command, accounts);
      state = ledger.applyEvent({ accounts, receipts: {} }, event);
    } catch (error) { asBadInput(error); }

    const summary = ledger.ledgerSummary(state);
    const result = { eventId, ...summary };
    tx.create(journalRef, { ...event, schemaVersion: 1, createdAt: FieldValue.serverTimestamp() });
    if (transactionRef) {
      tx.create(transactionRef, {
        eventId, requestId, eventType: kind, amountCents, effectiveDate,
        ...(kind === 'expense' ? { sourceKey: command.sourceKey } : {}),
        schemaVersion: 1, createdAt: FieldValue.serverTimestamp(),
      });
    }
    const summaryData = {
      ...summary, accounts: state.accounts, lastEventId: eventId,
      updatedAt: FieldValue.serverTimestamp(),
    };
    if (kind === 'opening') {
      tx.create(summaryRef, { ...summaryData, initializedAt: FieldValue.serverTimestamp() });
    } else {
      tx.update(summaryRef, summaryData);
    }
    tx.create(operationRef, {
      requestId, fingerprint, eventId, status: 'committed', result,
      createdAt: FieldValue.serverTimestamp(),
    });
    return { ...result, duplicate: false };
  });
}

module.exports = Object.fromEntries(
  Object.entries(OPERATIONS).map(([kind, { name }]) =>
    [name, (request) => performOperation(request, kind)])
);
